package main

// Cross-language contract: a scope.json produced by the PYTHON signer
// (rt.scope + rt._ed25519) must verify in Go's stdlib crypto/ed25519 with a
// byte-identical canonical form. The fixtures in testdata/ were generated by
// the Python signer with a fixed all-zeros seed (reproducible; test-only key).
// If either side's canonical form drifts, this test fails.

import (
	"encoding/json"
	"os"
	"testing"
)

func TestInteropPythonSignedScope(t *testing.T) {
	sb, err := os.ReadFile("testdata/py_signed_scope.json")
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	tb, err := os.ReadFile("testdata/py_trust.json")
	if err != nil {
		t.Fatalf("read trust fixture: %v", err)
	}
	var s Scope
	if err := json.Unmarshal(sb, &s); err != nil {
		t.Fatalf("unmarshal scope: %v", err)
	}
	var keys []string
	if err := json.Unmarshal(tb, &keys); err != nil {
		t.Fatalf("unmarshal trust: %v", err)
	}
	trust := map[string]bool{}
	for _, k := range keys {
		trust[k] = true
	}
	if !s.Verify() {
		t.Fatal("Go failed to verify a Python-signed scope (canonical-form or Ed25519 drift)")
	}
	s = s.WithTrust(trust)
	if !s.Decide("10.0.0.5").Allowed {
		t.Fatal("in-scope target denied")
	}
	if s.Decide("10.0.0.9").Allowed {
		t.Fatal("excluded target allowed")
	}
}
